{% set r=ref('mart_kpi_user_daily') %}
with expected as (select column_name from unnest(['event_dt', 'user_pseudo_id', 'user_id', 'gender', 'major', 'entry_year', 'user_type', 'is_deleted', 'is_mysql_mapped', 'platform_dominant', 'device_category_dominant', 'device_os_dominant', 'event_cnt_day', 'entry_event_cnt_day', 'core_action_cnt_day', 'session_cnt_day', 'engagement_msec_day', 'is_multi_session_user', 'first_seen_dt', 'first_signup_dt', 'is_new_user', 'is_new_signup', 'had_entry_prev_day', 'is_signup_retained_d1', 'is_signup_retained_d7', 'is_signup_retained_d14', 'is_signup_retained_d30', 'used_shop_flg', 'used_cafeteria_flg', 'used_bus_flg', 'used_board_flg', 'used_facility_flg', 'used_timetable_flg', 'used_account_flg', 'is_active_entry', 'is_active_any_event', 'has_core_action', 'used_main_flg', 'event_complete_start_dt', 'event_complete_dt', 'user_snapshot_at', 'build_id', 'computed_at', 'funnel_session_facts']) column_name), actual as (select column_name from `{{ r.database }}.{{ r.schema }}.INFORMATION_SCHEMA.COLUMNS` where table_name='{{ r.identifier }}')
select coalesce(e.column_name,a.column_name) as column_name from expected e full join actual a using(column_name) where e.column_name is null or a.column_name is null
